import pandas as pd


def run(inputs: dict[str, "pd.DataFrame"]) -> dict[str, "pd.DataFrame"]:
    postings = inputs["postings"]

    posted_cols = ["account_id", "post_seq", "post_date", "post_value", "running_total"]
    reject_cols = ["account_id", "reject_count"]

    if postings.empty:
        posted_totals = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "post_seq": pd.Series(dtype="int64"),
            "post_date": pd.Series(dtype="datetime64[us]"),
            "post_value": pd.Series(dtype="float64"),
            "running_total": pd.Series(dtype="float64"),
        })
        reject_counts = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "reject_count": pd.Series(dtype="int64"),
        })
        return {"posted_totals": posted_totals, "reject_counts": reject_counts}

    df = postings.sort_values(
        by=["account_id", "post_date", "post_seq"],
        kind="mergesort"
    ).reset_index(drop=True)

    posted_rows = []
    reject_rows = []

    prev_acct = None
    tot = 0.0
    rej = 0

    for row in df.itertuples(index=False):
        account_id = row.account_id
        post_seq = row.post_seq
        post_date = row.post_date
        qty = row.qty
        unit_price = row.unit_price

        if account_id != prev_acct:
            if prev_acct is not None:
                reject_rows.append((prev_acct, rej))
            tot = 0.0
            rej = 0
            prev_acct = account_id

        is_bad = (
            pd.isna(qty) or qty <= 0 or
            pd.isna(unit_price) or unit_price < 0
        )

        if is_bad:
            rej += 1
        else:
            v = qty * unit_price
            tot = tot + v
            posted_rows.append((account_id, post_seq, post_date, v, tot))

    if prev_acct is not None:
        reject_rows.append((prev_acct, rej))

    posted_totals = pd.DataFrame(posted_rows, columns=posted_cols)
    if not posted_totals.empty:
        posted_totals["account_id"] = posted_totals["account_id"].astype("int64")
        posted_totals["post_seq"] = posted_totals["post_seq"].astype("int64")
        posted_totals["post_date"] = pd.to_datetime(posted_totals["post_date"]).astype("datetime64[us]")
        posted_totals["post_value"] = posted_totals["post_value"].astype("float64")
        posted_totals["running_total"] = posted_totals["running_total"].astype("float64")
    else:
        posted_totals = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "post_seq": pd.Series(dtype="int64"),
            "post_date": pd.Series(dtype="datetime64[us]"),
            "post_value": pd.Series(dtype="float64"),
            "running_total": pd.Series(dtype="float64"),
        })

    reject_counts = pd.DataFrame(reject_rows, columns=reject_cols)
    if not reject_counts.empty:
        reject_counts["account_id"] = reject_counts["account_id"].astype("int64")
        reject_counts["reject_count"] = reject_counts["reject_count"].astype("int64")
    else:
        reject_counts = pd.DataFrame({
            "account_id": pd.Series(dtype="int64"),
            "reject_count": pd.Series(dtype="int64"),
        })

    return {"posted_totals": posted_totals, "reject_counts": reject_counts}
